using var cts = new CancellationTokenSource(budget);
var tasks = recipients.Select(r => quoteClient.AskAsync(r, cts.Token)).ToArray();
try { return PickBest(await Task.WhenAll(tasks)); }
catch (Exception) when (tasks.Any(t => t.IsFaulted || t.IsCanceled))
{
    var partial = tasks.Where(t => t.IsCompletedSuccessfully).Select(t => t.Result);
    return PickBest(partial);          // explicit partial-result branch
}

