[FunctionName("LoanBroker")]
public static async Task<long> Run([OrchestrationTrigger] IDurableOrchestrationContext ctx)
{
    var vendors = await ctx.CallActivityAsync<string[]>("GetVendors", null);
    var quotes = vendors.Select(v => ctx.CallActivityAsync<long>("Quote", v));
    var all = await Task.WhenAll(quotes);      // fan-in, replay-safe
    return all.Sum();                          // aggregate
}
